%[text] # Demo 4: Iterative Learning Control Experiment
%[text] Run this live script from the project root. Trajectory generation requires Symbolic Math Toolbox.
%[text] The build section only prepares the target. The trial loop operates the real stage and must be run by the experiment operator.
%[text] ## 1. Load settings and design the feedback controller
clear; close all;
    run("config/config_tunable.m");
projectRoot = pwd;
figToolsRoot = fullfile(fileparts(projectRoot), "FigTools");
addpath(figToolsRoot, fullfile(figToolsRoot, "src"));

load("config/data/pana_params.mat");
[plant, plantPath] = load_experiment_plant( ...
    projectRoot, plantDataFile, Ts);
Pd = plant.Pd;
Jn = plant.Jn;
Dn = plant.Dn;
Ndelay = plant.Ndelay;
fprintf("Sample rate: %.0f Hz, plant: %s\n", 1/Ts, plantPath); %[output:34e006af]

Pd0 = struct( ...
    "m", Jn, ...
    "d", Dn, ...
    "k", 0, ...
    "delay", Ndelay, ...
    "lp", [0, 0, 0]); % Current plant data uses the Demo 3 model without the legacy tau filter.
[~, Gn0] = modelCreate(Pd0, Ts, Pd.Frequency);
Pdn = Gn0.modelDelayed;

[fb, ~, ~] = fbDesign(Pd, Ts);
Kd = fb.K;
%%
%[text] ## Check stability and sensitivity before operating the stage
figure; %[output:03076361]
bopModel = bop;
bopModel.Title.String = "";
bode(Pdn, Pd, bopModel); %[output:03076361]
legend("Model", "Measured", "Location", "northwest"); %[output:03076361]
grid on; %[output:03076361]
pubfig(gcf); %[output:03076361]
%%
Smax = 2;
theta = linspace(0, 2*pi, 1000);

figure; %[output:24d3626a]
nyquistplot(Pdn*Kd, nop); hold on; %[output:24d3626a]
nyquistplot(Pd*Kd, nop); %[output:24d3626a]
plot(cos(theta)/Smax-1, sin(theta)/Smax, "k--"); hold off; %[output:24d3626a]
legend("Nominal", "Measured", "1/Smax boundary"); %[output:24d3626a]
title(""); %[output:24d3626a]
% pubfig(gcf);

figure; %[output:35ed762c]
S = feedback(1, Pd*Kd);
SmaxFrd = frd(Smax*ones(numel(Pd.Frequency), 1), ...
    Pd.Frequency, "FrequencyUnit", "Hz");
bopSensitivity = bop;
bopSensitivity.XLim = {[1, 1e3]};
bodemag(S, bopSensitivity); hold on; %[output:35ed762c]
bodemag(SmaxFrd, bopSensitivity, "k--"); hold off; %[output:35ed762c]
legend("Measured", "Smax"); %[output:35ed762c]
title(""); %[output:35ed762c]
% pubfig(gcf);
%%
%[text] ## 2. Design the learning and robustness filters
%[text] The nominal closed-loop inverse is implemented as $C+G\_n^{-1}$. The 400 Hz Q filter and the iteration-dependent learning gain reproduce the effective settings of the original experiment.
Ntrial = 20;
Fc = 420;             % Q-filter cutoff [Hz]
[Qz, Qp, Qgain] = butter(4, Fc/(1/(2*Ts)));
[Qsos, Qscale] = zp2sos(Qz, Qp, Qgain);
Q = zpk(Qz, Qp, Qgain, Ts);
Linv = feedback(Pdn, Kd);
J = feedback(Pd, Kd);

figure; %[output:0f9123cf]
bodemag(Q^2*(1-J/Linv), bop); hold on; %[output:0f9123cf]
bodemag(1-J/Linv, bop); %[output:0f9123cf]
bodemag(Q^2, bop); %[output:0f9123cf]
plot([1, 1/(2*Ts)], [0, 0], "k--"); hold off; %[output:0f9123cf]
ylim([-150, 5]); %[output:0f9123cf]
legend("Q^2(1-JL)", "1-JL", "Q^2", "Convergence boundary", ... %[output:0f9123cf]
    "Location", "southwest"); %[output:0f9123cf]
title("ILC convergence condition"); %[output:0f9123cf]
% pubfig(gcf);
%%
%[text] ## 3. Generate the reference trajectory
dist = 1.25;        % Travel distance [m]
v_max = 1.7;       % Maximum velocity [m/s]
a_max = 15.0;       % Maximum acceleration [m/s^2]
t_pause = 1.0;     % Dwell at the turn-around point [s]
t_pre = 1.5;       % Idle time before motion [s]
t_post = 1.5;      % Idle time after motion [s]

traj = generateMyProfile_TrajectTools( ...
    0.0, dist, v_max, a_max/2, Ts, t_pause, t_pre, t_post);
t = traj.time;
r = traj.pos(:);
Tend = t(end);
N = numel(r);
feedbackFlag = 1;

figure; %[output:35ace174]
tiledlayout(3, 1); %[output:35ace174]
nexttile; plot(t, traj.pos); title("Position"); grid on; %[output:35ace174]
ylabel("Position [m]"); %[output:35ace174]
nexttile; plot(t, traj.vel); title("Velocity"); grid on; %[output:35ace174]
ylabel("Velocity [m/s]"); %[output:35ace174]
nexttile; plot(t, traj.acc); title("Acceleration"); grid on; %[output:35ace174]
xlabel("Time [s]"); ylabel("Acceleration [m/s^2]"); %[output:35ace174]
% pubfig(gcf);
%%
%[text] ## 4. Build the tunable model
%[text] Run this section after every sampleRateHz change. Demo 4 shares the target with Demo 3. Publish/install the generated module, set the TwinCAT task to Ts, and activate the configuration before the trials.
run(fullfile(projectRoot, "exp03_FF", "setup_tunable.m")); %[output:491036df]
%%
%[text] ## 5. Run the ILC trials
%[text] **Operator action:** this section connects to external mode once, runs all trials, and disconnects when the sequence finishes or is interrupted. Existing `simulink/data/measurement_*.mat` parts are deleted before every capture.
open(ModelName);
confirmEachTrial = false; % Set true to inspect each result before continuing.
run(fullfile(projectRoot, "exp04_ILC", "obtainMeasurement.m")); %[output:9e5550f3] %[output:8d9bb019] %[output:8b7427c5] %[output:63f5026d]
%%
%[text] ## Save the result
resultFile = my_save_mat(sprintf("ilc_result_V%.3f", v_max), ... %[output:group:5b977f19] %[output:2293becd]
    "history", "completedTrials", "Kd", "traj", "Q", "Fc", ... %[output:2293becd]
    "Ts", "plantPath"); %[output:group:5b977f19] %[output:2293becd]
%%
%[text] ## 6. Inspect the learned result
iteration = completedTrials;
figure; %[output:63951289]
tiledlayout(3, 1); %[output:63951289]
nexttile; plot(t, history.r(:, iteration), t, history.y(:, iteration)); %[output:63951289]
grid on; ylabel("Position [m]"); legend(["Reference", "Position"]); %[output:63951289]
nexttile; plot(t, history.e(:, iteration)); %[output:63951289]
grid on; ylabel("Tracking error [m]"); %[output:63951289]
nexttile; plot(t, history.f(:, iteration), ... %[output:63951289]
    t, history.u(:, iteration)-history.f(:, iteration)); %[output:63951289]
grid on; xlabel("Time [s]"); ylabel("Input [A]"); legend("FF", "FB"); %[output:63951289]
linkaxes(findall(gcf, "Type", "axes"), "x"); %[output:63951289]
% pubfig(gcf);

figure; %[output:189d17d7]
semilogy(0:completedTrials-1, history.eNorm(1:completedTrials), "-o"); %[output:189d17d7]
grid on; xlabel("Iteration"); %[output:189d17d7]
ylabel("||e||_2"); title("ILC learning curve"); %[output:189d17d7]
% pubfig(gcf);

% fprintf("Completed %d trial(s). Result: %s\n", completedTrials, resultFile);

